<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

class SeedParc extends Command {
    protected $signature   = "parc:seed
        {--dry-run : N'effectue aucune écriture, affiche seulement le plan}
        {--force   : Saute la confirmation interactive}";
    protected $description = "Reinsertion du vrai parc panneaux CIBLE CI (337 panneaux, 30 communes, 13 formats, 7 catégories).";

