        $dry   = (bool) $this->option('dry-run');
        $force = (bool) $this->option('force');

        // ── created_by obligatoire (NOT NULL en base) ─────────────────
        $adminId = DB::table('users')
            ->whereIn('role', ['admin', 'super_admin'])
            ->orderBy('id')
            ->value('id');
        if (!$adminId) {
            $this->error("Aucun utilisateur admin trouvé — impossible d'assigner created_by.");
            return self::FAILURE;
        }

        // Tables vidées AVANT ré-insertion. On NE TOUCHE PAS :
        // users / taxes / external_agencies / clients / roles / permissions
        // (préservation explicite des données opérationnelles non-parc).
        $vider = [
            "satisfaction_surveys","commune_tax_payments","audit_logs","alerts",
            "piges","pose_tasks","invoices","propositions",
            "campaign_panels","campaigns","reservation_panels","reservations",
            "maintenances","client_contacts","client_users",
            "external_panels","panel_photos","panels",
            "zones","panel_formats","panel_categories","communes",
            "sessions","failed_jobs","jobs","cache","cache_locks","password_reset_tokens",
        ];

        // ── Récap avant exécution ────────────────────────────────────
        $this->info('═══════════════════════════════════════════════');
        $this->info('  parc:seed — réinsertion vrai parc CIBLE CI');
        $this->info('═══════════════════════════════════════════════');
        $this->line('  Admin utilisé pour created_by : ID '.$adminId);
        $this->line('  Tables à vider : '.count($vider));
        $total = 0;
        foreach ($vider as $t) {
            if (Schema::hasTable($t)) {
                $c = DB::table($t)->count();
                if ($c > 0) $this->line(sprintf('    %-26s %6d ligne(s)', $t, $c));
                $total += $c;
            }
        }
        $this->line('  ───────────────────');
        $this->line('  Total à supprimer : <fg=red>'.$total.'</> ligne(s)');
        $this->line('  Tables PRÉSERVÉES : users, taxes, external_agencies, clients, roles, permissions, migrations');

        if ($dry) {
            $this->warn('  ▶ DRY-RUN : aucune écriture.');
            return self::SUCCESS;
        }
        if (!$force && !$this->confirm('  ⚠  Confirmer la réinsertion ?', false)) {
            $this->line('  Annulé.');
            return self::SUCCESS;
        }

        DB::statement("SET FOREIGN_KEY_CHECKS=0");
